document.getElementById('importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());const features=data.type==='FeatureCollection'?data.features:[data];let imported=0;for(const f of features){if(f.geometry?.type!=='LineString'||!Array.isArray(f.geometry.coordinates)||f.geometry.coordinates.length<2)continue;const coordinates=f.geometry.coordinates.slice(0,MAX_CUSTOM_STOPS).filter(c=>Array.isArray(c)&&Number.isFinite(Number(c[0]))&&Number.isFinite(Number(c[1]))&&Number(c[0])>=-180&&Number(c[0])<=180&&Number(c[1])>=-90&&Number(c[1])<=90);if(coordinates.length<2)continue;const names=f.properties?.stopNames||[],connections=f.properties?.connections||[];const importedLine={id:makeId(),title:String(f.properties?.name||f.properties?.title||file.name.replace(/\.geojson$|\.json$/i,'')),color:/^#[0-9a-f]{6}$/i.test(f.properties?.color)?f.properties.color:'#314f88',stops:coordinates.map((c,i)=>{const connection=connections[i];return{name:String(names[i]||`Arrêt ${i+1}`),lat:+c[1],lng:+c[0],...(connection?.key?{stationKey:String(connection.key),stationNames:Array.isArray(connection.names)?connection.names:[],stationLines:Array.isArray(connection.lines)?connection.lines:[]}:{})}})};refreshCustomLineLogo(importedLine);userLines.push(importedLine);imported++}if(!imported)throw new Error('Aucune ligne LineString trouvée.');activeId=userLines[userLines.length-1].id;setDrawing(false);syncFields();persist();setStatus(`${imported} ligne(s) importée(s).`)}catch(err){setStatus('Import impossible : '+err.message,true)}finally{e.target.value=''}});
